/**
 * Writes `src/config.generated.ts` from `process.env` (after loading `.env` if present).
 * Run automatically before `tsc` via `npm run compile`.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import dotenv from "dotenv";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.join(__dirname, "..");
dotenv.config({ path: path.join(root, ".env") });

const url = process.env.SUPABASE_URL ?? "";
const key = process.env.SUPABASE_ANON_KEY ?? "";

const out = `/**
 * Auto-generated by scripts/gen-config.mjs — do not edit by hand.
 * Set SUPABASE_URL and SUPABASE_ANON_KEY in .env or the shell before \`npm run compile\`.
 */
export const SUPABASE_URL = ${JSON.stringify(url)};
export const SUPABASE_ANON_KEY = ${JSON.stringify(key)};
`;

const target = path.join(root, "src", "config.generated.ts");
fs.writeFileSync(target, out, "utf8");
